# phs/runtime/self_check.py
# -*- coding: utf-8 -*-
"""
PHS Runtime Self Check Provider.

Checks:
1. Model weights: WatermarkSeg v6 / SAM2 / Cutie / CosyVoice2 / COVER
2. GPU: CUDA / PyTorch
3. External tools: FFmpeg / FFprobe / fpcalc / OBS / VB-Cable / libvips
4. Port 8080 and output directory write permission
5. Markdown diagnostic report

Usage:
    python -m phs.runtime.self_check
    provider = get_provider()
    result = provider.run({"report_path": "runtime/reports/self_check.md"})
"""

from __future__ import annotations

import os
import platform
import shutil
import socket
import subprocess
import tempfile
import time
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple


PASS = "PASS"
WARN = "WARN"
FAIL = "FAIL"


@dataclass
class CheckItem:
    category: str
    name: str
    status: str
    detail: str
    suggestion: str = ""
    duration_ms: int = 0


@dataclass
class ModelSpec:
    name: str
    env: str
    min_mb_env: str
    min_mb: int
    candidates: Tuple[str, ...]


class RuntimeSelfCheckProvider:
    name = "runtime_self_check"
    version = "1.0.0"

    def __init__(self, root: Optional[Path] = None) -> None:
        self.root = root or self._detect_root()
        self.runtime_dir = Path(os.getenv("PHS_RUNTIME_DIR", str(self.root / "runtime")))
        self.models_dir = Path(os.getenv("PHS_MODELS_DIR", str(self.runtime_dir / "models")))
        self.report_dir = Path(os.getenv("PHS_REPORT_DIR", str(self.runtime_dir / "reports")))
        self.output_dir = Path(os.getenv("PHS_OUTPUT_DIR", str(self.runtime_dir / "outputs")))

    def run(self, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        payload = payload or {}
        started = time.perf_counter()

        checks: List[CheckItem] = []
        checks.extend(self.check_models(payload.get("models")))
        checks.extend(self.check_gpu())
        checks.extend(self.check_tools())
        checks.extend(self.check_port(int(payload.get("port", os.getenv("PHS_PORT", "8080")))))
        checks.extend(self.check_output_dir(Path(payload.get("output_dir", self.output_dir))))

        markdown = self.to_markdown(checks, total_ms=int((time.perf_counter() - started) * 1000))
        report_path = payload.get("report_path")
        if report_path is None:
            self.report_dir.mkdir(parents=True, exist_ok=True)
            report_path = self.report_dir / "self_check.md"
        report_path = Path(report_path)
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(markdown, encoding="utf-8")

        summary = self.summary(checks)
        return {
            "ok": summary["FAIL"] == 0,
            "provider": self.name,
            "version": self.version,
            "root": str(self.root),
            "runtime_dir": str(self.runtime_dir),
            "models_dir": str(self.models_dir),
            "summary": summary,
            "checks": [asdict(x) for x in checks],
            "markdown": markdown,
            "report_path": str(report_path),
        }

    def __call__(self, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        return self.run(payload)

    def check_models(self, overrides: Optional[Dict[str, str]] = None) -> List[CheckItem]:
        specs = self.model_specs()
        results: List[CheckItem] = []
        overrides = overrides or {}
        for spec in specs:
            t0 = time.perf_counter()
            env_path = overrides.get(spec.name) or os.getenv(spec.env)
            path = Path(env_path) if env_path else self._find_candidate(spec.candidates)
            min_mb = int(os.getenv(spec.min_mb_env, str(spec.min_mb)))
            min_bytes = min_mb * 1024 * 1024

            if path is None:
                results.append(self._item(
                    "模型权重", spec.name, FAIL,
                    f"未找到模型。搜索目录: {self.models_dir}",
                    f"设置 {spec.env} 或把权重放入 runtime/models 对应目录。",
                    t0,
                ))
                continue

            if not path.exists():
                results.append(self._item(
                    "模型权重", spec.name, FAIL,
                    f"路径不存在: {path}",
                    f"检查下载是否完成，或设置 {spec.env} 指向正确文件/目录。",
                    t0,
                ))
                continue

            size = self._path_size(path)
            size_mb = size / 1024 / 1024
            if size < min_bytes:
                results.append(self._item(
                    "模型权重", spec.name, FAIL,
                    f"存在但大小异常: {path}，{size_mb:.1f}MB < {min_mb}MB",
                    f"重新下载权重；如阈值不适用，可设置 {spec.min_mb_env}。",
                    t0,
                ))
            else:
                results.append(self._item(
                    "模型权重", spec.name, PASS,
                    f"{path}，{size_mb:.1f}MB，阈值≥{min_mb}MB",
                    "",
                    t0,
                ))
        return results

    def check_gpu(self) -> List[CheckItem]:
        results: List[CheckItem] = []
        t0 = time.perf_counter()
        try:
            import torch  # type: ignore

            cuda_ok = bool(torch.cuda.is_available())
            detail = f"PyTorch {torch.__version__}; CUDA available={cuda_ok}"
            if cuda_ok:
                count = torch.cuda.device_count()
                names = [torch.cuda.get_device_name(i) for i in range(count)]
                detail += f"; devices={names}"
                results.append(self._item("GPU", "CUDA/PyTorch", PASS, detail, "", t0))
            else:
                results.append(self._item(
                    "GPU", "CUDA/PyTorch", WARN, detail,
                    "未检测到 CUDA。可继续 CPU 模式，但 SAM2/CosyVoice2/Cutie 可能变慢；检查 NVIDIA 驱动、CUDA、torch 版本。",
                    t0,
                ))
        except Exception as exc:
            results.append(self._item(
                "GPU", "CUDA/PyTorch", FAIL,
                f"PyTorch 导入失败: {exc}",
                "安装匹配当前 CUDA 的 torch，或确认虚拟环境已激活。",
                t0,
            ))
        return results

    def check_tools(self) -> List[CheckItem]:
        results: List[CheckItem] = []
        tool_specs = [
            ("FFmpeg", ("ffmpeg",), True, "安装 FFmpeg 并加入 PATH。"),
            ("FFprobe", ("ffprobe",), True, "安装 FFmpeg 套件并确认 ffprobe 在 PATH 中。"),
            ("fpcalc", ("fpcalc",), False, "安装 Chromaprint/fpcalc，用于音频指纹或去重。"),
            ("libvips", ("vips", "vips.exe"), False, "安装 libvips，并把 vips 加入 PATH；或安装 pyvips 依赖。"),
        ]
        for name, bins, required, suggestion in tool_specs:
            results.append(self._check_executable(name, bins, required, suggestion))
        results.append(self._check_obs())
        results.append(self._check_vb_cable())
        return results

    def check_port(self, port: int) -> List[CheckItem]:
        t0 = time.perf_counter()
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(1)
        try:
            sock.bind(("127.0.0.1", port))
            sock.close()
            return [self._item("运行环境", f"端口 {port}", PASS, f"127.0.0.1:{port} 可用", "", t0)]
        except OSError as exc:
            sock.close()
            active = self._can_connect(port)
            status = WARN if active else FAIL
            detail = f"端口不可绑定: {exc}; active_service={active}"
            suggestion = f"关闭占用 {port} 的进程，或设置 PHS_PORT 使用其他端口。"
            return [self._item("运行环境", f"端口 {port}", status, detail, suggestion, t0)]

    def check_output_dir(self, output_dir: Path) -> List[CheckItem]:
        t0 = time.perf_counter()
        try:
            output_dir.mkdir(parents=True, exist_ok=True)
            with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=output_dir, delete=False) as fp:
                fp.write("phs self check")
                tmp = Path(fp.name)
            tmp.unlink(missing_ok=True)
            return [self._item("运行环境", "输出目录写入权限", PASS, f"可写: {output_dir}", "", t0)]
        except Exception as exc:
            return [self._item(
                "运行环境", "输出目录写入权限", FAIL,
                f"不可写: {output_dir}; {exc}",
                "检查目录权限、磁盘空间，或设置 PHS_OUTPUT_DIR 到可写目录。",
                t0,
            )]

    def to_markdown(self, checks: List[CheckItem], total_ms: int = 0) -> str:
        summary = self.summary(checks)
        overall = FAIL if summary[FAIL] else (WARN if summary[WARN] else PASS)
        lines = [
            "# PHS Runtime 自检报告",
            "",
            f"- **总体状态**: `{overall}`",
            f"- **生成时间**: `{time.strftime('%Y-%m-%d %H:%M:%S')}`",
            f"- **耗时**: `{total_ms}ms`",
            f"- **系统**: `{platform.platform()}`",
            f"- **项目根目录**: `{self.root}`",
            f"- **Runtime目录**: `{self.runtime_dir}`",
            f"- **模型目录**: `{self.models_dir}`",
            "",
            "## 汇总",
            "",
            f"- PASS: **{summary[PASS]}**",
            f"- WARN: **{summary[WARN]}**",
            f"- FAIL: **{summary[FAIL]}**",
            "",
            "## 明细",
            "",
            "| 类别 | 检查项 | 状态 | 详情 | 修复建议 | 耗时 |",
            "|---|---|---:|---|---|---:|",
        ]
        for item in checks:
            lines.append(
                f"| {self._md(item.category)} | {self._md(item.name)} | **{item.status}** | "
                f"{self._md(item.detail)} | {self._md(item.suggestion or '-')} | {item.duration_ms}ms |"
            )
        lines += [
            "",
            "## 判定说明",
            "",
            "- `PASS`: 检查通过。",
            "- `WARN`: 不阻塞启动，但可能影响画质、性能或部分功能。",
            "- `FAIL`: 交付前应修复，否则主链路可能无法运行。",
            "",
        ]
        return "\n".join(lines)

    @staticmethod
    def summary(checks: List[CheckItem]) -> Dict[str, int]:
        return {
            PASS: sum(1 for x in checks if x.status == PASS),
            WARN: sum(1 for x in checks if x.status == WARN),
            FAIL: sum(1 for x in checks if x.status == FAIL),
        }

    def model_specs(self) -> List[ModelSpec]:
        return [
            ModelSpec(
                "WatermarkSeg v6", "PHS_WATERMARK_V6_MODEL", "PHS_WATERMARK_V6_MIN_MB", 1,
                (
                    "watermarkseg/v6.*", "watermarkseg/*v6*.*", "watermark/v6.*",
                    "watermark/*v6*.*", "*watermark*v6*.*",
                ),
            ),
            ModelSpec(
                "SAM2", "PHS_SAM2_CHECKPOINT", "PHS_SAM2_MIN_MB", 800,
                (
                    "sam2/sam2_hiera_large.pt", "sam2/*.pt", "*sam2*hiera*large*.pt",
                ),
            ),
            ModelSpec(
                "Cutie", "PHS_CUTIE_CHECKPOINT", "PHS_CUTIE_MIN_MB", 100,
                (
                    "cutie/*.pth", "cutie/*.pt", "*cutie*.pth", "*cutie*.pt",
                ),
            ),
            ModelSpec(
                "CosyVoice2", "PHS_COSYVOICE2_MODEL", "PHS_COSYVOICE2_MIN_MB", 100,
                (
                    "CosyVoice2*", "cosyvoice2*", "CosyVoice2*/**/*", "cosyvoice2*/**/*",
                ),
            ),
            ModelSpec(
                "COVER", "PHS_COVER_MODEL", "PHS_COVER_MIN_MB", 1,
                (
                    "cover/*", "COVER/*", "*cover*.*", "*COVER*.*",
                ),
            ),
        ]

    def _find_candidate(self, patterns: Iterable[str]) -> Optional[Path]:
        for pat in patterns:
            p = Path(pat)
            if p.is_absolute() and p.exists():
                return p
            exact = self.models_dir / pat
            if exact.exists():
                return exact
            matches = list(self.models_dir.glob(pat))
            matches = [m for m in matches if m.exists()]
            if matches:
                matches.sort(key=lambda x: self._path_size(x), reverse=True)
                return matches[0]
        return None

    def _check_executable(self, name: str, bins: Tuple[str, ...], required: bool, suggestion: str) -> CheckItem:
        t0 = time.perf_counter()
        found = None
        for b in bins:
            found = shutil.which(b)
            if found:
                break
        if not found:
            return self._item("外部工具", name, FAIL if required else WARN, "未在 PATH 中找到", suggestion, t0)

        version = self._version(found)
        return self._item("外部工具", name, PASS, f"{found}; {version}", "", t0)

    def _check_obs(self) -> CheckItem:
        t0 = time.perf_counter()
        candidates = [
            shutil.which("obs64"),
            shutil.which("obs"),
            r"C:\Program Files\obs-studio\bin\64bit\obs64.exe",
            r"C:\Program Files\OBS Studio\bin\64bit\obs64.exe",
        ]
        for raw in candidates:
            if raw and Path(raw).exists():
                return self._item("外部工具", "OBS", PASS, f"找到 OBS: {raw}", "", t0)
        return self._item(
            "外部工具", "OBS", WARN, "未找到 OBS 可执行文件",
            "安装 OBS Studio；如只做离线编译可忽略，直播推流前必须配置。",
            t0,
        )

    def _check_vb_cable(self) -> CheckItem:
        t0 = time.perf_counter()
        if platform.system().lower() != "windows":
            return self._item("外部工具", "VB-Cable", WARN, "非 Windows 环境，跳过声卡设备枚举", "Windows 直播机需安装 VB-Cable。", t0)

        try:
            cmd = [
                "powershell", "-NoProfile", "-Command",
                "Get-CimInstance Win32_SoundDevice | Select-Object -ExpandProperty Name",
            ]
            out = subprocess.run(cmd, capture_output=True, text=True, timeout=5, encoding="utf-8", errors="ignore")
            names = out.stdout.lower()
            if "vb-audio" in names or "cable" in names:
                return self._item("外部工具", "VB-Cable", PASS, "检测到 VB-Audio/CABLE 声卡设备", "", t0)
            return self._item(
                "外部工具", "VB-Cable", WARN, "未检测到 VB-Cable 声卡设备",
                "安装 VB-Cable，并在 OBS/TTS 音频链路中选择对应虚拟声卡。",
                t0,
            )
        except Exception as exc:
            return self._item(
                "外部工具", "VB-Cable", WARN, f"设备枚举失败: {exc}",
                "手动确认 Windows 声音设备中是否存在 VB-Cable。",
                t0,
            )

    @staticmethod
    def _detect_root() -> Path:
        here = Path(__file__).resolve()
        for p in [here.parent, *here.parents]:
            if (p / "phs").exists() or (p / "app").exists():
                return p
        return Path.cwd().resolve()

    @staticmethod
    def _path_size(path: Path) -> int:
        if path.is_file():
            return path.stat().st_size
        total = 0
        if path.is_dir():
            for p in path.rglob("*"):
                if p.is_file():
                    try:
                        total += p.stat().st_size
                    except OSError:
                        pass
        return total

    @staticmethod
    def _version(exe: str) -> str:
        for args in ([exe, "-version"], [exe, "--version"], [exe, "-v"]):
            try:
                out = subprocess.run(args, capture_output=True, text=True, timeout=4, errors="ignore")
                text = (out.stdout or out.stderr or "").strip().splitlines()
                if text:
                    return text[0][:160]
            except Exception:
                continue
        return "version unknown"

    @staticmethod
    def _can_connect(port: int) -> bool:
        try:
            with socket.create_connection(("127.0.0.1", port), timeout=0.5):
                return True
        except OSError:
            return False

    @staticmethod
    def _md(text: str) -> str:
        return str(text).replace("|", "\\|").replace("\n", " ").strip()

    @staticmethod
    def _item(category: str, name: str, status: str, detail: str, suggestion: str, t0: float) -> CheckItem:
        return CheckItem(category, name, status, detail, suggestion, int((time.perf_counter() - t0) * 1000))


def get_provider(**kwargs: Any) -> RuntimeSelfCheckProvider:
    return RuntimeSelfCheckProvider(**kwargs)


def create_provider(**kwargs: Any) -> RuntimeSelfCheckProvider:
    return get_provider(**kwargs)


def run_self_check(payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    return get_provider().run(payload)


if __name__ == "__main__":
    result = run_self_check()
    print(result["markdown"])
    raise SystemExit(0 if result["ok"] else 1)
